#include <iostream>
#include <string>

int main() {
    int score = 78;
    char grade;
    if (score >= 90) {
        grade = 'A';
    } else if (score >= 75) {
        grade = 'B';
    } else if (score >= 60) {
        grade = 'C';
    } else {
        grade = 'F';
    }
    std::cout << "score " << score << " -> grade " << grade << std::endl;

    std::string status = (score >= 60) ? "pass" : "fail";
    std::cout << status << std::endl;
    return 0;
}

#include <iostream>

int main() {
    int sum = 0;
    for (int i = 1; i <= 5; i++) {
        sum += i;
    }
    std::cout << "for sum: " << sum << std::endl;

    int n = 40;
    int steps = 0;
    while (n > 1) {
        n = n / 2;
        steps++;
    }
    std::cout << "while steps: " << steps << std::endl;

    int counter = 0;
    do {
        counter++;
    } while (counter < 3);
    std::cout << "do-while counter: " << counter << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> data = {5, 2, 9, 1, 7};
    int n = data.size();

    for (int i = 0; i < n - 1; i++) {
        bool swapped = false;
        for (int j = 0; j < n - 1 - i; j++) {
            if (data[j] > data[j + 1]) {
                int tmp = data[j];
                data[j] = data[j + 1];
                data[j + 1] = tmp;
                swapped = true;
            }
        }
        if (!swapped) {
            break;
        }
    }

    bool first = true;
    for (int v : data) {
        if (!first) std::cout << ' ';
        std::cout << v;
        first = false;
    }
    std::cout << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int binarySearch(const std::vector<int>& arr, int target) {
    int lo = 0;
    int hi = arr.size() - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    std::vector<int> data = {1, 3, 5, 7, 9, 11};
    std::cout << "find 9: index " << binarySearch(data, 9) << std::endl;
    std::cout << "find 4: index " << binarySearch(data, 4) << std::endl;
    return 0;
}

#include <iostream>

long long factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

int digitSum(int n) {
    if (n == 0) return 0;
    return n % 10 + digitSum(n / 10);
}

int main() {
    std::cout << "factorial(5) = " << factorial(5) << std::endl;
    std::cout << "digitSum(927) = " << digitSum(927) << std::endl;
    return 0;
}
